head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf30693";
scwin.opt = null;
scwin.regcncl = "";
scwin.flag = "false";
scwin.arrCode = undefined;
scwin.arrName = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_codeName", fn: function () { return String(((__cv) => (__cv !== undefined && __cv !== null && __cv !== "") ? __cv : "")(dma_pageContext.get("code"))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.arrCode =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30693' }); }

try { scwin.arrName =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30693' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf30693.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_3_onsubmit
 * @description form_3 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_3_onsubmit = function(e){
    try {
        let ev = e;
        let event = ev;
        let __self = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30693.form_3_onsubmit' }); }
};

/**
 * @method
 * @name slc_selCode_onchange
 * @description slc_selCode 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_selCode_onchange = function(e){
    try {
        let ev = e;
        let event = ev;
        let __self = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.changeCodeName();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30693.slc_selCode_onchange' }); }
};

/**
 * @method
 * @name slc_selCode_ondblclick
 * @description slc_selCode 더블클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_selCode_ondblclick = function(e){
    try {
        let ev = e;
        let event = ev;
        let __self = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.returnValue();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30693.slc_selCode_ondblclick' }); }
};

/**
 * @method
 * @name btn_returnValue_onclick
 * @description btn_returnValue 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_returnValue_onclick = function(e){
    try {
        let ev = e;
        let event = ev;
        let __self = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.returnValue()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30693.btn_returnValue_onclick' }); }
};

/**
 * @method
 * @name btn_winClose_onclick
 * @description btn_winClose 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_winClose_onclick = function(e){
    try {
        let ev = e;
        let event = ev;
        let __self = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.winClose()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30693.btn_winClose_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name __on_enter_2_ipt_codename
 * @description on enter 2 ipt codename 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_2_ipt_codename = async function(e){
    try {
        let ev = e;
        let event = ev;
        let __self = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        if(($c.util.getKeyCode(ev))===13){ await scwin.searchCom() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf30693.__on_enter_2_ipt_codeName' }); }
};

/**
 * @method
 * @name sel
 * @description sel 처리
 * @param {*} jaum jaum
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sel = async function (jaum) {
    let obj = (document.frm || { elements: [] });
    let iCount = 0;
    scwin.arrReset();
    for (let j = 0; j < jr.length; j++) {
        if (jr[j] != null && jaum === jr[j].jtt) {
            if (scwin.flag !== 'true') {
                if (jr[j].jname.indexOf("변경전사명") < 1) {
                    if (scwin.regcncl === "1") {
                        scwin.arrCode[iCount] = jr[j].jcode;
                        scwin.arrName[iCount] = jr[j].jname;
                        iCount++;
                    } else {
                        if (jr[j].jname.indexOf("폐지") < 1) {
                            scwin.arrCode[iCount] = jr[j].jcode;
                            scwin.arrName[iCount] = jr[j].jname;
                            iCount++;
                        }
                    }
                }
            } else {
                if (scwin.regcncl === "1") {
                    scwin.arrCode[iCount] = jr[j].jcode;
                    scwin.arrName[iCount] = jr[j].jname;
                    iCount++;
                } else {
                    if (jr[j].jname.indexOf("폐지") < 1) {
                        scwin.arrCode[iCount] = jr[j].jcode;
                        scwin.arrName[iCount] = jr[j].jname;
                        iCount++;
                    }
                }
            }
        }
    }
    await scwin.setSelectBox();
};

/**
 * @method
 * @name setSelectBox
 * @description set Select Box 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setSelectBox = async function () {
    let obj = (document.frm || { elements: [] });
    $c.util.getComponent('slc_selCode').options.length = scwin.arrCode.length;
    for (i = 0; i < scwin.arrCode.length; i++) {
        $c.util.getComponent('slc_selCode').getItemText(i) = '(' + scwin.arrCode[i] + ')' + scwin.arrName[i];
        $c.util.getComponent('slc_selCode').options[i].value = scwin.arrCode[i];
    }
    if (scwin.arrCode.length !== 0) {
        $c.util.getComponent("ipt_codeName").setValue(scwin.arrName[0]);
        $c.util.getComponent('slc_selCode').setSelectedIndex(0);
        $c.util.getComponent("slc_selCode").focus();
    } else {
        await $c.win.alert('해당 종목이 존재하지 않습니다.');
    }
};

/**
 * @method
 * @name searchCom
 * @description search Com 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCom = async function () {
    let obj = (document.frm || { elements: [] });
    const searchValue = $c.util.getComponent('ipt_codeName').getValue();
    if (searchValue.length !== 0) {
        if (scwin.isNumber(searchValue)) {
            await scwin.searchCode(searchValue);
        } else {
            await scwin.searchName(searchValue);
        }
    }
};

/**
 * @method
 * @name isNumber
 * @description is Number 처리
 * @param {*} searchValue searchValue
 * @returns {void}
 * @hidden N
 */
scwin.isNumber = function (searchValue) {
    const numCheck = /^[0-9]+$/;
    if (numCheck.test(searchValue)) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name arrReset
 * @description arr Reset 처리
 * @returns {void}
 * @hidden N
 */
scwin.arrReset = function () {
    scwin.arrCode.length = 0;
    scwin.arrName.length = 0;
};

/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @param {*} searchValue searchValue
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function (searchValue) {
    let iCount = 0;
    scwin.arrReset();
    for (let j = 0; j < jr.length; j++) {
        if (searchValue === jr[j].jcode.substring(0, searchValue.length)) {
            if (jr[j].jname.indexOf("변경전사명") < 1) {
                if (scwin.regcncl === "1") {
                    scwin.arrCode[iCount] = jr[j].jcode;
                    scwin.arrName[iCount] = jr[j].jname;
                    iCount++;
                } else {
                    if (jr[j].jname.indexOf("폐지") < 1) {
                        scwin.arrCode[iCount] = jr[j].jcode;
                        scwin.arrName[iCount] = jr[j].jname;
                        iCount++;
                    }
                }
            }
        }
    }
    await scwin.setSelectBox();
};

/**
 * @method
 * @name searchName
 * @description search Name 처리
 * @param {*} searchValue searchValue
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchName = async function (searchValue) {
    let iCount = 0;
    scwin.arrReset();
    for (let j = 0; j < jr.length; j++) {
        if (searchValue === jr[j].jname.substring(0, searchValue.length)) {
            if (scwin.regcncl === "1") {
                scwin.arrCode[iCount] = jr[j].jcode;
                scwin.arrName[iCount] = jr[j].jname;
                iCount++;
            } else {
                if (jr[j].jname.indexOf("폐지") < 1) {
                    scwin.arrCode[iCount] = jr[j].jcode;
                    scwin.arrName[iCount] = jr[j].jname;
                    iCount++;
                }
            }
        }
    }
    await scwin.setSelectBox();
};

/**
 * @method
 * @name returnValue
 * @description return Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.returnValue = function () {
    let obj = (document.frm || { elements: [] });
    let selectedIndex = $c.util.getComponent('slc_selCode').getSelectedIndex();
    if (selectedIndex !== -1) {
        if (scwin.opt === 0) {
            eval("opener.document.forms[0].comCode.value='" + scwin.arrCode[selectedIndex] + "'");
        } else {
            if (scwin.opt === 1) {
                eval("opener.document.forms[0].comName.value='" + scwin.arrName[selectedIndex] + "'");
            } else {
                if (scwin.opt === 2) {
                    if (opener.document.forms[0].pageNum != null) {
                        opener.document.forms[0].pageNum.value = "1";
                    }
                    eval("opener.document.forms[0].comCode.value='" + scwin.arrCode[selectedIndex] + "'");
                    eval("opener.document.forms[0].comName.value='" + scwin.arrName[selectedIndex] + "'");
                } else {
                    if (scwin.opt === 3) {
                        eval("opener.document.forms[0].comCode.value='" + scwin.arrCode[selectedIndex] + "'");
                        eval("opener.document.forms[0].code.value='" + scwin.arrCode[selectedIndex] + "'");
                        (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (__id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  __id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (__id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  __id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).doSubmit === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (__id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  __id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).doSubmit() : void 0), $c.win.closePopup([]));
                    } else {
                        if (scwin.opt === 9) {
                            eval("((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).parent).document.forms[0].comCode.value='" + scwin.arrCode[selectedIndex] + "'");
                            eval("((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).parent).document.forms[0].comName.value='" + scwin.arrName[selectedIndex] + "'");
                        }
                    }
                }
            }
        }
        if (scwin.arrName[selectedIndex].indexOf("변경전사명") > 1) {
            scwin.setBeforeName(scwin.arrCode[selectedIndex], scwin.arrName[selectedIndex]);
        } else {
            scwin.setBeforeName();
        }
    }
    scwin.winClose();
};

/**
 * @method
 * @name changeCodeName
 * @description change Code Name 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeCodeName = function () {
    let obj = (document.frm || { elements: [] });
    let selectedIndex = $c.util.getComponent('slc_selCode').getSelectedIndex();
    let name = $c.util.getComponent('slc_selCode')[selectedIndex].text;
    if (name !== '') {
        $c.util.getComponent("ipt_codeName").setValue(scwin.arrName[selectedIndex]);
    }
};

/**
 * @method
 * @name winClose
 * @description win Close 처리
 * @returns {void}
 * @hidden N
 */
scwin.winClose = function () {
    $c.win.closePopup();
};

/**
 * @method
 * @name setBeforeName
 * @description set Before Name 처리
 * @param {*} code code
 * @param {*} name name
 * @returns {void}
 * @hidden N
 */
scwin.setBeforeName = function (code, name) {
    if (code == null) {
        ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).parent).self.before.innerHTML = "";
        ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).parent).document.form.beforeName.value = "";
    } else {
        const nowName = scwin.findcode(code);
        ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).parent).document.form.comName.value = nowName;
        ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).parent).self.before.innerHTML = name;
        ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).parent).document.form.beforeName.value = name;
    }
};

/**
 * @method
 * @name findcode
 * @description findcode 처리
 * @param {*} jcode jcode
 * @returns {void}
 * @hidden N
 */
scwin.findcode = function (jcode) {
    let name = '';
    for (let j = 0; j < jr.length; j++) {
        if (jr[j].jcode === jcode) {
            if (jr[j].jname.indexOf("변경전사명") < 1) {
                name = jr[j].jname;
                break;
            }
        }
    }
    return name;
};
